#!/usr/bin/env Rscript
############################################################
# 47_pearson_full_15282.R
#
# The two FULL Pearson relevance networks (Butte et al., PNAS 2000):
# all A7 patients and all A9 patients, no subsampling.
#
# Input: the pre-ARSyN matrix regenerated by 34_regen_prepro_noARSyN.R, i.e.
# this repository's own preprocessing with ARSyNseq() omitted. 17,481 genes,
# the same gene universe as the published matrix.
#
# Edge criterion, per clade:
#   r on log2(x+1), no rank transform -- the Pearson twin of
#   42_spearman_full_15282.R, same matrix, same threshold formula
#   t = r*sqrt(n-2)/sqrt(1-r^2),  df = n-2
#   alpha = 0.05 / NP,  NP = 15282*15281/2 = 116,762,121 pairs
#
# IMPORTANT, and stated again in the README that ships with the output:
# n differs between the clades (A7 = 65, A9 = 202), so the two Bonferroni
# thresholds are NOT the same number and the two networks are NOT directly
# comparable by edge count or density. A correlation threshold at fixed alpha
# is a function of n; the larger cohort will always look denser. Comparisons
# between the clades must be made at a matched number of edges (see
# 31_full_network_topology.R) or on the 200 leave-x-out networks, which are
# all n = 60 by construction.

suppressPackageStartupMessages({ library(data.table); library(RhpcBLASctl) })
blas_set_num_threads(24); omp_set_num_threads(24)

BASE <- "/STORAGE/csbig/jruiz/cesc_network/ARACNE_AP/Leave_x_out"
SRC  <- BASE  # matriz del repo: 03_preprocessing/2_7 y 2_8 (identicas byte a byte)
OUT  <- file.path(BASE, "47_pearson_full_15282"); dir.create(OUT, recursive = TRUE, showWarnings = FALSE)
log_msg <- function(...) cat(sprintf("[%s] ", format(Sys.time(), "%H:%M:%S")), sprintf(...), "\n", sep = "")

MAT <- c(A7 = file.path(SRC, "2_7_Full_counts_A7_annot.tsv"),
         A9 = file.path(SRC, "2_8_Full_counts_A9_annot.tsv"))

summ <- list()
for (cl in c("A7", "A9")) {
  dt <- fread(MAT[[cl]], sep = "\t", header = TRUE)
  genes <- dt[[1]]
  X <- log2(as.matrix(dt[, -1, with = FALSE]) + 1); rm(dt); gc(FALSE)
  NG <- nrow(X); n <- ncol(X); NP <- NG * (NG - 1) / 2
  THR <- { tq <- qt(1 - (0.05 / NP) / 2, n - 2); tq / sqrt(n - 2 + tq^2) }
  log_msg("%s: %d genes x %d muestras | pares=%s | umbral |r| >= %.6f",
          cl, NG, n, format(NP, big.mark = ","), THR)

  R <- stats::cor(t(X)); rm(X); gc(FALSE)   # Pearson: no rank transform
  R[!is.finite(R)] <- 0
  R[lower.tri(R, diag = TRUE)] <- 0
  idx <- which(R >= THR | R <= -THR)
  ij  <- arrayInd(idx, dim(R)); rho <- R[idx]; rm(R, idx); gc(FALSE)
  o <- order(abs(rho), decreasing = TRUE)
  ij <- ij[o, , drop = FALSE]; rho <- rho[o]

  ED <- data.table(Gene1 = genes[ij[, 1]], Gene2 = genes[ij[, 2]], r = round(rho, 6))
  f <- file.path(OUT, sprintf("Pearson_full_network_%s.tsv.gz", cl))
  fwrite(ED, f, sep = "\t", quote = FALSE, compress = "gzip")

  nodes <- length(unique(c(ij[, 1], ij[, 2])))
  summ[[cl]] <- data.table(
    clade = cl, n_muestras = n, n_genes = NG, pares_evaluados = NP,
    umbral_abs_r = round(THR, 6), aristas = nrow(ED), nodos_conectados = nodes,
    pct_genes_conectados = round(100 * nodes / NG, 2),
    grado_promedio = round(2 * nrow(ED) / nodes, 2),
    aristas_negativas = sum(rho < 0),
    pct_negativas = round(100 * sum(rho < 0) / nrow(ED), 2),
    r_min_abs = round(min(abs(rho)), 6), r_max_abs = round(max(abs(rho)), 6))
  log_msg("  aristas=%s  nodos=%s (%.1f%%)  negativas=%.1f%%  archivo=%s MB",
          format(nrow(ED), big.mark = ","), format(nodes, big.mark = ","),
          100 * nodes / NG, 100 * sum(rho < 0) / nrow(ED),
          round(file.size(f) / 1e6, 1))
  rm(ij, rho, ED); gc(FALSE)
}
ST <- rbindlist(summ)
fwrite(ST, file.path(OUT, "Pearson_full_network_summary.csv"))
print(ST)
log_msg("Done -> %s", OUT)
